mod solution;

fn main() {
    let cases = [
    (r#"edges=(0,1),(1,2),(1,3),(3,4) values=[1,2,3,4,5]"#, r#"14"#),
    (r#"edges=(0,1),(1,2),(1,3),(3,4) values=[1,1,1,1,1]"#, r#"4"#),
    (r#"
edges=(0,1),(1,2),(1,3),(3,4) values=[1,1,1,1,1]
"#, r#"4"#),
    (r#"  
edges=(0,1),(1,2),(1,3),(3,4) values=[1,2,3,4,5]
  "#, r#"14"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS heavy-light");
}
